<?php
include '../components/connect.php'; session_start();
if(empty($_SESSION['admin_id'])){header('location:index.php');exit;}
$message=[]; $env_file=dirname(__DIR__).'/.env';
$get=function($key,$default=''){ $v=getenv($key); return $v===false?$default:$v; };
if(isset($_POST['save_settings'])){
  $provider=strtolower(trim((string)($_POST['ai_provider']??'local'))); if(!in_array($provider,['local','openai','auto'],true))$provider='local';
  $model=trim((string)($_POST['openai_model']??'gpt-4.1-mini')); $base=trim((string)($_POST['openai_base_url']??'https://api.openai.com/v1')); $key=trim((string)($_POST['openai_api_key']??''));
  if($key==='')$key=$get('OPENAI_API_KEY','');
  $ep_store=trim((string)($_POST['easypaisa_store_id']??$get('EASYPAISA_STORE_ID',''))); $ep_secret=trim((string)($_POST['easypaisa_webhook_secret']??'')); if($ep_secret==='')$ep_secret=$get('EASYPAISA_WEBHOOK_SECRET',''); $ep_required=isset($_POST['easypaisa_require_signature'])?'1':'0';
  $content="APP_ENV=development\nAI_PROVIDER=".str_replace(["\r","\n"],'',$provider)."\nOPENAI_API_KEY=".str_replace(["\r","\n"],'',$key)."\nOPENAI_MODEL=".str_replace(["\r","\n"],'',$model)."\nOPENAI_BASE_URL=".str_replace(["\r","\n"],'',$base)."\nEASYPAISA_STORE_ID=".str_replace(["\r","\n"],'',$ep_store)."\nEASYPAISA_WEBHOOK_SECRET=".str_replace(["\r","\n"],'',$ep_secret)."\nEASYPAISA_REQUIRE_WEBHOOK_SIGNATURE=".$ep_required."\n";
  if(file_put_contents($env_file,$content,LOCK_EX)!==false){putenv('AI_PROVIDER='.$provider);putenv('OPENAI_MODEL='.$model);putenv('OPENAI_BASE_URL='.$base);if($key!=='')putenv('OPENAI_API_KEY='.$key);$message[]='AI settings saved. API key is stored only in the local .env file.';}else$message[]='Could not save .env. Check file permissions.';
}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI and payment settings</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.1.1/css/all.min.css"><link rel="stylesheet" href="../css/admin_style.css"></head><body><?php include '../components/admin_header.php'; ?><section class="form-container"><form method="post"><h3>AI and payment settings</h3><?php foreach($message as $m): ?><div class="message"><span><?= htmlspecialchars($m,ENT_QUOTES,'UTF-8'); ?></span></div><?php endforeach; ?><span>AI provider</span><select class="box" name="ai_provider"><option value="local" <?= $get('AI_PROVIDER','local')==='local'?'selected':''; ?>>Local knowledge</option><option value="openai" <?= $get('AI_PROVIDER')==='openai'?'selected':''; ?>>OpenAI API</option><option value="auto" <?= $get('AI_PROVIDER')==='auto'?'selected':''; ?>>Auto with local fallback</option></select><span>OpenAI API key</span><input class="box" type="password" name="openai_api_key" placeholder="Leave blank to keep existing key"><span>model</span><input class="box" name="openai_model" value="<?= htmlspecialchars($get('OPENAI_MODEL','gpt-4.1-mini'),ENT_QUOTES,'UTF-8'); ?>"><span>base URL</span><input class="box" name="openai_base_url" value="<?= htmlspecialchars($get('OPENAI_BASE_URL','https://api.openai.com/v1'),ENT_QUOTES,'UTF-8'); ?>"><h3>Easypaisa webhook</h3><span>merchant/store ID</span><input class="box" name="easypaisa_store_id" value="<?= htmlspecialchars($get('EASYPAISA_STORE_ID',''),ENT_QUOTES,'UTF-8'); ?>"><span>webhook secret</span><input class="box" type="password" name="easypaisa_webhook_secret" placeholder="Leave blank to keep existing secret"><label><input type="checkbox" name="easypaisa_require_signature" value="1" <?= $get('EASYPAISA_REQUIRE_WEBHOOK_SIGNATURE','1')!=='0'?'checked':''; ?>> require signature before marking orders paid</label><input type="submit" name="save_settings" class="btn" value="save settings"></form></section><script src="../js/admin_script.js"></script></body></html>
